import org.junit.jupiter.api.Test;

/**
 * On a FOAF clique store with the direct-adjacency index, the packed f-tree aggregate's quote for a grouped 3-cycle
 * carries the lanes it packs rather than the joined rows the kernels enumerate.
 */
class LmdbNativeCycleQuoteTest {

	private static final String GROUPED_CYCLE = "PREFIX foaf: <http://xmlns.com/foaf/0.1/>\n"
			+ "SELECT ?a (COUNT(DISTINCT ?c) AS ?n) WHERE {\n"
			+ "  ?a foaf:knows ?b . ?b foaf:knows ?c . ?c foaf:knows ?a .\n"
			+ "} GROUP BY ?a";

	private static final String CYCLE = "PREFIX foaf: <http://xmlns.com/foaf/0.1/>\n"
			+ "SELECT ?a ?b ?c WHERE { ?a foaf:knows ?b . ?b foaf:knows ?c . ?c foaf:knows ?a . }";

	@Test
	void theLeapfrogJoinIsPricedWithinTwiceThePackedFtreeOnACycle() throws IOException {
		// measured on 3000 people with adjacency (2026-11-03): wcoj 14.4 ms, packedFtree 10.6 ms; the old
		// set-at-a-time quote priced wcoj at 1.7 ms (measured over quoted 7.2x in the harness median)
		Map<String, Double> costs = withCliqueStore(connection -> NativeProposalFeatures.costs(connection
				.prepareTupleQuery(CYCLE)
				.explain(Explanation.Level.Telemetry)
				.toGenericPlanNode(), "wcoj"));
		assertThat(costs).as("row decision prices").containsKeys("wcoj", "packedFtree");
		assertThat(costs.get("wcoj")).as("prices: %s", costs)
				.isBetween(0.5D * costs.get("packedFtree"), 2D * costs.get("packedFtree"));
	}

	@Test
	void thePackedAggregateIsQuotedPerLaneOnAGroupedCycle() throws IOException {
		Map<String, Map<String, Double>> features = withCliqueStore(connection -> NativeProposalFeatures.offering(
				connection.prepareTupleQuery(GROUPED_CYCLE).explain(Explanation.Level.Telemetry).toGenericPlanNode(),
				"packedFtreeAggregate"));
		Map<String, Double> packed = features.get("packedFtreeAggregate");
		Map<String, Double> sequential = features.get("nestedLoop");
		assertThat(sequential).as("the sequential path at the same decision: %s", features).isNotNull();
		// lanes are packed and folded, never enumerated as rows
		assertThat(packed.getOrDefault("GENERATED_ROW", 0D)).as("packed: %s", features).isZero();
		assertThat(packed.getOrDefault("INTERPRETED_ROW", 0D)).as("packed: %s", features).isZero();
		assertThat(packed.getOrDefault("BATCH_ROW", 0D)).as("packed: %s", features).isGreaterThan(0D);
		// one update per demanded lane that carries a row (the group key ?a and the counted ?c): at most one per
		// joined row for each of the two demanded nodes, where the sequential path updates once per joined row
		assertThat(packed.getOrDefault("GROUP_UPDATE", 0D)).as("packed against sequential: %s", features)
				.isGreaterThan(0D)
				.isLessThanOrEqualTo(2D * sequential.getOrDefault("GROUP_UPDATE", 0D));
	}

	/** Runs {@code probe} against a 300-person FOAF clique store with the direct-adjacency index built. */
	private static <T> T withCliqueStore(java.util.function.Function<SailRepositoryConnection, T> probe)
			throws IOException {
		Path dataDir = Files.createTempDirectory("rdf4j-lmdb-cycle-quote");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setForceSync(false)
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbStore store = new LmdbStore(dataDir.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				new FoafCliqueDataGenerator(300, 30, 3, 5, 900, 12345L).populate(connection);
			}
			assertThat(AdjacencyEngagementTestAccess.buildNow(store)).as("adjacency index built").isTrue();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				return probe.apply(connection);
			}
		} finally {
			repository.shutDown();
			try (Stream<Path> paths = Files.walk(dataDir)) {
				paths.sorted(Comparator.reverseOrder()).forEach(path -> path.toFile().delete());
			}
		}
	}
}
